const i = $input.first().json || {};
const phone = String(i.phone || i.properties?.phone || '').trim();
const email = String(i.email || i.properties?.email || '').trim().toLowerCase();
const message = String(i.message || i.properties?.message || '').trim();
const name = i.name || i.firstName || i.properties?.name || '';
const subject = i.subject || 'Yakwetu Sinema';
const channelPref = i.channelPref || i.channel_pref || (email ? 'email' : phone ? 'sms' : 'both');
const channels = Array.isArray(i.channels) ? i.channels : null;

if (!message) {
  return [{ json: { ...i, skipped: true, reason: 'no message', phone, email } }];
}
if (!phone && !email) {
  return [{ json: { ...i, skipped: true, reason: 'no contact', phone, email } }];
}

return [{
  json: {
    ...i,
    userId: i.userId || i.user_id || null,
    phone,
    email,
    name,
    message,
    subject,
    channelPref,
    channel_pref: channelPref,
    channels,
    scenario: i.scenario || 'n8n_notify',
    sessionId: i.sessionId || i.session_id || null,
    ctaUrl: i.ctaUrl || i.url || null,
    ctaLabel: i.ctaLabel || null,
    imageUrl: i.imageUrl || i.poster || null,
    filmTitle: i.filmTitle || i.title || i.cartTitle || i.boughtTitle || null,
    bundleTitle: i.bundleTitle || (Array.isArray(i.pickTitles) ? i.pickTitles.join(' + ') : i.pickTitle) || null,
    genre: i.genre || null,
    priceKes: i.priceKes || i.totalKes || null,
    discountPct: i.discountPct || null,
    watchedTitle: i.watchedTitle || null,
    headline: i.headline || null,
    badge: i.badge || null,
    skipped: false,
  },
}];
